-- Base de marquage SMD de Compozit.
--
-- Source : relevé ponctuel de smd.yooneed.one (pages de préfixe publiques),
-- transformé en table locale pour que la recherche reste instantanée et
-- fonctionne hors connexion.

CREATE TABLE IF NOT EXISTS marking_codes (
    id INT AUTO_INCREMENT PRIMARY KEY,
    code VARCHAR(24) NOT NULL,
    part_number VARCHAR(120) NOT NULL,
    manufacturer VARCHAR(80) NOT NULL DEFAULT '',
    package_name VARCHAR(80) NOT NULL DEFAULT '',
    function_label VARCHAR(120) NOT NULL DEFAULT '',
    description VARCHAR(255) NOT NULL DEFAULT '',
    source VARCHAR(40) NOT NULL DEFAULT '',
    KEY idx_marking_code (code),
    KEY idx_marking_part (part_number),
    KEY idx_marking_manufacturer (manufacturer)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

TRUNCATE TABLE marking_codes;


































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































